import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Parametreler","description":"","frontmatter":{},"headers":[],"relativePath":"tr/qgc-user-guide/setup_view/parameters.md","filePath":"tr/qgc-user-guide/setup_view/parameters.md"}`),a={name:`tr/qgc-user-guide/setup_view/parameters.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="parametreler" tabindex="-1">Parametreler <a class="header-anchor" href="#parametreler" aria-label="Permalink to “Parametreler”">​</a></h1><p><em>Parametreler</em> ekranı, araçla ilişkili parametrelerden herhangi birini bulmanıza ve düzenlemenizi sağlar.</p><div class="tip custom-block"><p class="custom-block-title">Having trouble?</p><p>If parameters fail to download, see <a href="./../troubleshooting/parameter_download.html">Parameter Download Failures</a>.</p></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>PX4 Pro ve ArduPilot farklı parametre setleri kullanır, ancak her ikisi de bu bölümde açıklandığı gibi yönetilir.</p></div><h2 id="bir-parametreyi-bulma" tabindex="-1">Bir Parametreyi Bulma <a class="header-anchor" href="#bir-parametreyi-bulma" aria-label="Permalink to “Bir Parametreyi Bulma”">​</a></h2><p>Parametreler gruplar halinde düzenlenmiştir. Select a group of parameters to view by clicking on the buttons to the left.</p><p>Ayrıca _ Search_ alanına bir terim girerek bir parametre için _ arama _ yapabilirsiniz. Bu size girilen alt diziyi içeren tüm parametre adlarının ve açıklamalarının bir listesini gösterecektir (aramayı sıfırlamak için ** Clear ** tuşuna basın).</p><h2 id="changing-a-parameter" tabindex="-1">Changing a Parameter <a class="header-anchor" href="#changing-a-parameter" aria-label="Permalink to “Changing a Parameter”">​</a></h2><p>To change the value of a parameter click on the parameter row in a group or search list. This will open a side dialog in which you can update the value (this dialog also provides additional detailed information about the parameter - including whether a reboot is required for the change to take effect).</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p><strong>Save</strong> butonuna basıldığında, parametre sessizce ve otomatik olarak bağlı cihaza yüklenir. Parametreye bağlı olarak, değişikliğin etki etmesi için uçuş kontrolcüsünü yeniden başlatmanız gerekebilir.</p></div><h2 id="araclar" tabindex="-1">Araçlar <a class="header-anchor" href="#araclar" aria-label="Permalink to “Araçlar”">​</a></h2><p>Ekranın sağ üstündeki <strong>Tools</strong> menüsünden ek seçenekler seçebilirsiniz.</p><p><strong>Refresh</strong> <br> Tüm parametreleri araçtan tekrar isteyerek yenileyin.</p><p><strong>Reset all to defaults</strong> <br>Tüm parametleri varsayıla değerlerine sıfırlayın.</p><p><strong>Load from file / Save to file</strong> <br>Parametreleri var olan bir dosyadan yükleyin veya mevcut parametre ayarlarınızı bir dosyaya kaydedin.</p><p><strong>Clear RC to Param</strong> <br>Bu, RC verici kontrolleri ve parametreleri arasındaki tüm ilişkileri siler. For more information see: <a href="./../setup_view/radio.html#param-tuning-channels-px4">Radio Setup &gt; Param Tuning Channels</a>.</p><p><strong>Reboot Vehicle</strong> <br>Aracı yeniden başlatın (bazı parametre değişimlerinden sonra gereklidir).</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};